// Avoma on an API key: every operation in Avoma's published API (meetings, notes, transcripts, recordings, calls,
// insights, scorecards, templates, categories, meeting types and outcomes, engagement and revenue analytics, users,
// webhooks). actions.json is generated by `bun scripts/openapi-actions.ts avoma`; notes being ready and scheduler
// bookings start automations by webhook (triggers.ts).
import { z } from "zod";
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

export const api: Api = {
  name: "Avoma",
  base: "https://api.avoma.com",
  tokenHelp: "Avoma → Settings → Organization → Developer",
};

const BASE = "https://api.avoma.com/";
const actions = await specActions(new URL("./actions.json", import.meta.url), api);
// the spec says nothing for these
actions.get_user!.description = "Get one Avoma user: name, email, role, teams. Takes the user's uuid from list_users.";
actions.list_users!.description = "List the Avoma organization's users: uuid, name, email, role, teams.";

export const avoma: OwnApp = {
  app: "avoma",
  name: "Avoma",
  logo: "/logos/avoma.png",
  keyField: {
    label: "API key",
    help: "In Avoma (an admin): Settings → Organization → Developer → Add API Key. Name it Emplio, pick the scope (organization-wide sees every shared meeting; a user scope sees one person's), create it, and copy the whole key as shown (CLIENT_KEY:CLIENT_SECRET). API access is on Avoma's business plans; check yours on Avoma's pricing page.",
    placeholder: "CLIENT_KEY:CLIENT_SECRET",
  },
  async check(key) {
    await call(api, key, { method: "GET", path: "/v1/users/", query: [], headers: [] }, {});
  },
  push: {
    events,
    triggers,
    start: (key, connection, event) => watch(api, key, connection, event),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery, key) => receive(api, delivery, key),
    wanted,
  },
  actions: {
    ...actions,
    next_page: {
      description: "The next page of any Avoma list (meetings, notes, calls, users...): pass the `next` link the last page ended with.",
      readOnly: true,
      input: z.object({ next: z.string().describe("The `next` link from the previous page, https://api.avoma.com/v1/...") }),
      run: async (i: { next: string }, key: string) => {
        if (!i.next.startsWith(BASE)) throw new AppsError("next: give the link Avoma returned, starting https://api.avoma.com/");
        const u = new URL(i.next);
        return call(api, key, { method: "GET", path: `${u.pathname}${u.search}`, query: [], headers: [] }, {});
      },
    },
  },
};
